-- C10-A056 growth/governance: duplicates+safe merge, segments, campaigns (NO-OP provider), intake, reports, privacy, Customer 360, RLS/grants.
DO $g$ BEGIN IF to_regclass('c10_demo.a056_tickets') IS NULL THEN RAISE EXCEPTION 'A056_PIPELINE_REQUIRED'; END IF; END $g$;

CREATE TABLE c10_demo.a056_dup_candidates(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, customer_a bigint NOT NULL, customer_b bigint NOT NULL,
 reason text NOT NULL, score int NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN('open','dismissed','merged')), created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(customer_a<customer_b), UNIQUE(business_id,customer_a,customer_b),
 FOREIGN KEY(customer_a,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id),
 FOREIGN KEY(customer_b,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_merge_log(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, survivor_id bigint NOT NULL, loser_id bigint NOT NULL UNIQUE,
 actor uuid NOT NULL, reason text, loser_snapshot jsonb NOT NULL, moved jsonb NOT NULL, request_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,request_key));
CREATE TABLE c10_demo.a056_segments(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), definition jsonb NOT NULL,
 version bigint NOT NULL DEFAULT 1, request_key text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(business_id,request_key), UNIQUE(id,tenant_id,business_id),
 FOREIGN KEY(business_id,tenant_id) REFERENCES c10_demo.businesses(id,tenant_id));
CREATE TABLE c10_demo.a056_campaigns(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120),
 channel text NOT NULL CHECK(channel IN('email','sms','phone','whatsapp','post')), segment_id bigint NOT NULL, template text CHECK(length(template)<=2000),
 status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','dispatched_noop')), provider text NOT NULL DEFAULT 'NOOP' CHECK(provider='NOOP'), version bigint NOT NULL DEFAULT 1,
 request_key text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), dispatched_at timestamptz, UNIQUE(business_id,request_key), UNIQUE(id,tenant_id,business_id),
 FOREIGN KEY(segment_id,tenant_id,business_id) REFERENCES c10_demo.a056_segments(id,tenant_id,business_id));
CREATE TABLE c10_demo.a056_campaign_recipients(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id bigint NOT NULL, business_id bigint NOT NULL, campaign_id bigint NOT NULL, customer_id bigint NOT NULL,
 decision text NOT NULL CHECK(decision IN('send','blocked')), reason text NOT NULL, provider_status text NOT NULL CHECK(provider_status IN('NOOP_NOT_SENT','BLOCKED_NOT_SENT')),
 created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(campaign_id,customer_id),
 FOREIGN KEY(campaign_id,tenant_id,business_id) REFERENCES c10_demo.a056_campaigns(id,tenant_id,business_id),
 FOREIGN KEY(customer_id,tenant_id,business_id) REFERENCES c10_demo.a056_customers(id,tenant_id,business_id));

-- posted (A049 status=posted) order links, read only through the A049 overview contract
CREATE FUNCTION c10_demo.a056_posted_links(p_business bigint) RETURNS TABLE(customer_id bigint,link_id bigint,order_id bigint,estimate_total numeric,created_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
SELECT k.customer_id,k.id,k.a049_order_id,round(k.quantity*k.net_unit_price,2),k.created_at FROM c10_demo.a056_order_links k
JOIN jsonb_array_elements(COALESCE(c10_demo.a056_order_status(p_business)->'items','[]')) x ON (x->>'id')::bigint=k.a049_order_id AND x->>'status'='posted'
WHERE k.business_id=p_business AND k.adapter='A049_CANONICAL' $f$;

-- ---------- duplicates & safe merge ----------
CREATE FUNCTION c10_demo.a056_scan_duplicates_v1(p_business bigint,p_request text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; n int; o int;
BEGIN
 t:=c10_demo.a056_require(p_business,NULL,'customer.merge');
 h:=c10_demo.a056_h(p_business::text);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'scan_duplicates',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 WITH pairs AS (
  SELECT a.id x,b.id y,'email_match' r,100 s FROM c10_demo.a056_customers a JOIN c10_demo.a056_customers b ON b.business_id=a.business_id AND a.id<b.id AND a.email_norm=b.email_norm WHERE a.business_id=p_business AND a.status='active' AND b.status='active'
  UNION ALL SELECT a.id,b.id,'phone_match',90 FROM c10_demo.a056_customers a JOIN c10_demo.a056_customers b ON b.business_id=a.business_id AND a.id<b.id AND a.phone_norm=b.phone_norm WHERE a.business_id=p_business AND a.status='active' AND b.status='active'
  UNION ALL SELECT LEAST(k.customer_id,b.id),GREATEST(k.customer_id,b.id),'contact_email_match',80 FROM c10_demo.a056_contacts k JOIN c10_demo.a056_customers b ON b.business_id=k.business_id AND b.email_norm=k.email_norm AND b.id<>k.customer_id
   JOIN c10_demo.a056_customers a ON a.id=k.customer_id WHERE k.business_id=p_business AND k.status='active' AND a.status='active' AND b.status='active'
  UNION ALL SELECT a.id,b.id,'name_match',60 FROM c10_demo.a056_customers a JOIN c10_demo.a056_customers b ON b.business_id=a.business_id AND a.id<b.id AND a.kind=b.kind AND lower(a.display_name)=lower(b.display_name) WHERE a.business_id=p_business AND a.status='active' AND b.status='active'),
 best AS (SELECT DISTINCT ON (x,y) x,y,r,s FROM pairs ORDER BY x,y,s DESC)
 INSERT INTO c10_demo.a056_dup_candidates(tenant_id,business_id,customer_a,customer_b,reason,score) SELECT t,p_business,x,y,r,s FROM best ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS n=ROW_COUNT;
 SELECT count(*) INTO o FROM c10_demo.a056_dup_candidates WHERE business_id=p_business AND status='open';
 PERFORM c10_demo.a056_log(t,p_business,'duplicates.scan','customer',NULL,p_request,jsonb_build_object('created',n));
 RETURN c10_demo.a056_done(p_business,p_request,'scan_duplicates',h,jsonb_build_object('created',n,'open',o));
END $f$;
CREATE FUNCTION c10_demo.a056_list_duplicate_candidates_v1(p_business bigint,p_status text DEFAULT 'open',p_limit int DEFAULT 50,p_offset int DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE lim int; off int; tot int; items jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'customer.merge'); SELECT * INTO lim,off FROM c10_demo.a056_page(p_limit,p_offset);
 SELECT count(*) INTO tot FROM c10_demo.a056_dup_candidates WHERE business_id=p_business AND (p_status IS NULL OR status=p_status);
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',d.id,'customer_a',d.customer_a,'customer_b',d.customer_b,'reason',d.reason,'score',d.score,'status',d.status,
  'names',jsonb_build_array((SELECT display_name FROM c10_demo.a056_customers WHERE id=d.customer_a),(SELECT display_name FROM c10_demo.a056_customers WHERE id=d.customer_b)),
  'versions',jsonb_build_array((SELECT version FROM c10_demo.a056_customers WHERE id=d.customer_a),(SELECT version FROM c10_demo.a056_customers WHERE id=d.customer_b))) ORDER BY d.score DESC,d.id),'[]') INTO items
 FROM (SELECT * FROM c10_demo.a056_dup_candidates WHERE business_id=p_business AND (p_status IS NULL OR status=p_status) ORDER BY score DESC,id LIMIT lim OFFSET off) d;
 RETURN jsonb_build_object('items',items,'total',tot,'limit',lim,'offset',off);
END $f$;
CREATE FUNCTION c10_demo.a056_dismiss_duplicate_v1(p_candidate bigint,p_request text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE d c10_demo.a056_dup_candidates%ROWTYPE; h text; prev jsonb;
BEGIN
 SELECT * INTO d FROM c10_demo.a056_dup_candidates WHERE id=p_candidate FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(d.business_id,NULL,'customer.merge',false,true);
 h:=c10_demo.a056_h(p_candidate::text); prev:=c10_demo.a056_idem_check(d.business_id,p_request,'dismiss_dup',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF d.status<>'open' THEN RAISE EXCEPTION 'A056_DUP_TRANSITION'; END IF;
 UPDATE c10_demo.a056_dup_candidates SET status='dismissed' WHERE id=p_candidate;
 PERFORM c10_demo.a056_log(d.tenant_id,d.business_id,'duplicate.dismiss','duplicate',p_candidate,p_request);
 RETURN c10_demo.a056_done(d.business_id,p_request,'dismiss_dup',h,jsonb_build_object('id',p_candidate,'status','dismissed'));
END $f$;
CREATE FUNCTION c10_demo.a056_merge_customers_v1(p_survivor bigint,p_loser bigint,p_expected_survivor bigint,p_expected_loser bigint,p_request text,p_reason text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE s c10_demo.a056_customers%ROWTYPE; l c10_demo.a056_customers%ROWTYPE; h text; prev jsonb; b bigint; mv jsonb:='{}'; n int; nv bigint; tbl text; sup record;
BEGIN
 IF p_survivor IS NULL OR p_loser IS NULL OR p_survivor=p_loser THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 SELECT business_id INTO b FROM c10_demo.a056_customers WHERE id=p_survivor;
 IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(b,NULL,'customer.merge',false,true);
 h:=c10_demo.a056_h(p_survivor::text,p_loser::text,p_expected_survivor::text,p_expected_loser::text,p_reason);
 prev:=c10_demo.a056_idem_check(b,p_request,'merge_customers',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 PERFORM 1 FROM c10_demo.a056_customers WHERE id IN(p_survivor,p_loser) ORDER BY id FOR UPDATE;
 SELECT * INTO s FROM c10_demo.a056_customers WHERE id=p_survivor; SELECT * INTO l FROM c10_demo.a056_customers WHERE id=p_loser;
 IF l.id IS NULL OR l.business_id<>s.business_id THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 IF s.status<>'active' OR l.status<>'active' THEN RAISE EXCEPTION 'A056_CUSTOMER_NOT_ACTIVE'; END IF;
 IF s.version<>p_expected_survivor OR l.version<>p_expected_loser THEN RAISE EXCEPTION 'A056_STALE_CUSTOMER'; END IF;
 IF c10_demo.a056_txt(p_reason,500) IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 FOREACH tbl IN ARRAY ARRAY['a056_contacts','a056_history','a056_consent_events','a056_leads','a056_enquiries','a056_opportunities','a056_quotations','a056_order_links','a056_followups','a056_tickets','a056_campaign_recipients'] LOOP
  IF tbl='a056_campaign_recipients' THEN EXECUTE format('DELETE FROM c10_demo.%I r WHERE r.customer_id=$1 AND EXISTS(SELECT 1 FROM c10_demo.%I x WHERE x.campaign_id=r.campaign_id AND x.customer_id=$2)',tbl,tbl) USING p_loser,p_survivor; END IF;
  EXECUTE format('UPDATE c10_demo.%I SET customer_id=$1 WHERE customer_id=$2',tbl) USING p_survivor,p_loser; GET DIAGNOSTICS n=ROW_COUNT; mv:=mv||jsonb_build_object(tbl,n);
 END LOOP;
 UPDATE c10_demo.a056_contacts SET is_primary=false WHERE customer_id=p_survivor AND is_primary AND id IN(SELECT id FROM c10_demo.a056_contacts WHERE customer_id=p_survivor AND is_primary ORDER BY id OFFSET 1);
 DELETE FROM c10_demo.a056_comm_prefs WHERE customer_id=p_loser AND EXISTS(SELECT 1 FROM c10_demo.a056_comm_prefs WHERE customer_id=p_survivor);
 UPDATE c10_demo.a056_comm_prefs SET customer_id=p_survivor WHERE customer_id=p_loser;
 -- loser opt-outs must still bind the survivor identity
 FOR sup IN SELECT * FROM c10_demo.a056_suppressions WHERE customer_id=p_loser AND lifted_at IS NULL LOOP
  INSERT INTO c10_demo.a056_suppressions(tenant_id,business_id,channel,purpose,addr_hash,customer_id) VALUES(sup.tenant_id,sup.business_id,sup.channel,sup.purpose,'cust:'||p_survivor,p_survivor) ON CONFLICT DO NOTHING;
 END LOOP;
 -- survivor keeps its own primary data; loser identifiers preserved as a contact when different
 IF l.email_norm IS NOT NULL AND l.email_norm IS DISTINCT FROM s.email_norm OR l.phone_norm IS NOT NULL AND l.phone_norm IS DISTINCT FROM s.phone_norm THEN
  INSERT INTO c10_demo.a056_contacts(tenant_id,business_id,site_id,customer_id,name,role,email,phone,email_norm,phone_norm,request_key,created_by)
  VALUES(s.tenant_id,s.business_id,s.site_id,s.id,left(l.display_name,200),'merged record',l.email,l.phone,l.email_norm,l.phone_norm,'mg-'||p_request,c10_demo.actor_uid());
 END IF;
 UPDATE c10_demo.a056_customers SET tags=(SELECT COALESCE(array_agg(DISTINCT x),'{}') FROM unnest(s.tags||l.tags) x),version=version+1,updated_at=now() WHERE id=p_survivor RETURNING version INTO nv;
 UPDATE c10_demo.a056_customers SET status='merged',merged_into=p_survivor,version=version+1,updated_at=now() WHERE id=p_loser;
 UPDATE c10_demo.a056_dup_candidates SET status='merged' WHERE status='open' AND (customer_a IN(p_survivor,p_loser) AND customer_b IN(p_survivor,p_loser));
 UPDATE c10_demo.a056_dup_candidates SET status='dismissed' WHERE status='open' AND (customer_a=p_loser OR customer_b=p_loser);
 INSERT INTO c10_demo.a056_merge_log(tenant_id,business_id,survivor_id,loser_id,actor,reason,loser_snapshot,moved,request_key) VALUES(s.tenant_id,s.business_id,p_survivor,p_loser,c10_demo.actor_uid(),c10_demo.a056_txt(p_reason,500),c10_demo.a056_cust_json(l),mv,p_request);
 PERFORM c10_demo.a056_hist(s.tenant_id,s.business_id,s.site_id,p_survivor,'system','internal','Merged customer #'||p_loser||' into this record','mgh-'||p_request);
 PERFORM c10_demo.a056_log(s.tenant_id,s.business_id,'customer.merge','customer',p_survivor,p_request,jsonb_build_object('loser',p_loser,'moved',mv));
 RETURN c10_demo.a056_done(s.business_id,p_request,'merge_customers',h,jsonb_build_object('survivor_id',p_survivor,'loser_id',p_loser,'moved',mv,'version',nv));
END $f$;

-- ---------- segments ----------
CREATE FUNCTION c10_demo.a056_validate_segment(d jsonb) RETURNS void LANGUAGE plpgsql IMMUTABLE AS $f$
#variable_conflict use_column
DECLARE k text;
BEGIN
 IF d IS NULL OR jsonb_typeof(d)<>'object' THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 FOR k IN SELECT jsonb_object_keys(d) LOOP IF k NOT IN('kind','tags_any','site_id','min_posted_orders','max_days_since_purchase','has_consent') THEN RAISE EXCEPTION 'A056_INVALID'; END IF; END LOOP;
 IF d ? 'kind' AND d->>'kind' NOT IN('person','organization') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF d ? 'tags_any' AND (jsonb_typeof(d->'tags_any')<>'array' OR jsonb_array_length(d->'tags_any')>20) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF d ? 'site_id' AND (d->>'site_id')::bigint<1 THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF d ? 'min_posted_orders' AND ((d->>'min_posted_orders')::int NOT BETWEEN 0 AND 10000) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF d ? 'max_days_since_purchase' AND ((d->>'max_days_since_purchase')::int NOT BETWEEN 0 AND 36500) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF d ? 'has_consent' AND (jsonb_typeof(d->'has_consent')<>'object' OR d->'has_consent'->>'channel' NOT IN('email','sms','phone','whatsapp','post') OR d->'has_consent'->>'purpose' NOT IN('marketing','service')) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'A056_INVALID';
END $f$;
CREATE FUNCTION c10_demo.a056_segment_ids(p_business bigint,d jsonb) RETURNS bigint[] LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE r bigint[];
BEGIN
 WITH pl AS (SELECT customer_id,count(*) n,max(created_at) last_at FROM c10_demo.a056_posted_links(p_business) GROUP BY 1)
 SELECT COALESCE(array_agg(c.id ORDER BY c.id),'{}') INTO r FROM c10_demo.a056_customers c LEFT JOIN pl ON pl.customer_id=c.id
 WHERE c.business_id=p_business AND c.status='active' AND c10_demo.a056_row_ok(c.tenant_id,c.business_id,c.site_id)
  AND (NOT d ? 'kind' OR c.kind=d->>'kind')
  AND (NOT d ? 'tags_any' OR c.tags && ARRAY(SELECT jsonb_array_elements_text(d->'tags_any')))
  AND (NOT d ? 'site_id' OR c.site_id=(d->>'site_id')::bigint)
  AND (NOT d ? 'min_posted_orders' OR COALESCE(pl.n,0)>=(d->>'min_posted_orders')::int)
  AND (NOT d ? 'max_days_since_purchase' OR (pl.last_at IS NOT NULL AND pl.last_at>=now()-make_interval(days=>(d->>'max_days_since_purchase')::int)))
  AND (NOT d ? 'has_consent' OR (c10_demo.a056_consent_state(c.id,d->'has_consent'->>'channel',d->'has_consent'->>'purpose')->>'can_send')::boolean);
 RETURN r;
END $f$;
CREATE FUNCTION c10_demo.a056_save_segment_v1(p_business bigint,p_segment bigint,p_name text,p_definition jsonb,p_expected bigint,p_request text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; id bigint; nv bigint;
BEGIN
 t:=c10_demo.a056_require(p_business,NULL,'segment.write');
 h:=c10_demo.a056_h(p_segment::text,p_name,p_definition::text,p_expected::text);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'save_segment',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 PERFORM c10_demo.a056_validate_segment(p_definition);
 IF p_segment IS NULL THEN
  INSERT INTO c10_demo.a056_segments(tenant_id,business_id,name,definition,request_key,created_by) VALUES(t,p_business,c10_demo.a056_txt(p_name,120,true),p_definition,p_request,c10_demo.actor_uid()) RETURNING a056_segments.id,version INTO id,nv;
 ELSE
  UPDATE c10_demo.a056_segments SET name=c10_demo.a056_txt(p_name,120,true),definition=p_definition,version=version+1 WHERE a056_segments.id=p_segment AND business_id=p_business AND version=p_expected RETURNING a056_segments.id,version INTO id,nv;
  IF id IS NULL THEN RAISE EXCEPTION 'A056_STALE_SEGMENT'; END IF;
 END IF;
 PERFORM c10_demo.a056_log(t,p_business,'segment.save','segment',id,p_request);
 RETURN c10_demo.a056_done(p_business,p_request,'save_segment',h,jsonb_build_object('segment_id',id,'version',nv));
END $f$;
CREATE FUNCTION c10_demo.a056_list_segments_v1(p_business bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
BEGIN PERFORM c10_demo.a056_require(p_business,NULL,'segment.write');
 RETURN jsonb_build_object('items',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'definition',definition,'version',version) ORDER BY id DESC) FROM c10_demo.a056_segments WHERE business_id=p_business),'[]'));
END $f$;
CREATE FUNCTION c10_demo.a056_evaluate_segment_v1(p_segment bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE s c10_demo.a056_segments%ROWTYPE; ids bigint[];
BEGIN
 SELECT * INTO s FROM c10_demo.a056_segments WHERE id=p_segment; IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(s.business_id,NULL,'segment.write',false,true);
 ids:=c10_demo.a056_segment_ids(s.business_id,s.definition);
 RETURN jsonb_build_object('count',cardinality(ids),'customer_ids',to_jsonb(ids));
END $f$;

-- ---------- campaigns: consent-aware, provider-neutral NO-OP (nothing is ever sent) ----------
CREATE FUNCTION c10_demo.a056_create_campaign_v1(p_business bigint,p_name text,p_channel text,p_segment bigint,p_template text,p_request text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; id bigint;
BEGIN
 t:=c10_demo.a056_require(p_business,NULL,'campaign.write');
 h:=c10_demo.a056_h(p_name,p_channel,p_segment::text,p_template);
 prev:=c10_demo.a056_idem_check(p_business,p_request,'create_campaign',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_channel NOT IN('email','sms','phone','whatsapp','post') OR NOT EXISTS(SELECT 1 FROM c10_demo.a056_segments WHERE id=p_segment AND business_id=p_business) THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 INSERT INTO c10_demo.a056_campaigns(tenant_id,business_id,name,channel,segment_id,template,request_key,created_by) VALUES(t,p_business,c10_demo.a056_txt(p_name,120,true),p_channel,p_segment,c10_demo.a056_txt(p_template,2000),p_request,c10_demo.actor_uid()) RETURNING a056_campaigns.id INTO id;
 PERFORM c10_demo.a056_log(t,p_business,'campaign.create','campaign',id,p_request);
 RETURN c10_demo.a056_done(p_business,p_request,'create_campaign',h,jsonb_build_object('campaign_id',id,'status','draft','version',1));
END $f$;
CREATE FUNCTION c10_demo.a056_dispatch_campaign_v1(p_campaign bigint,p_request text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE c c10_demo.a056_campaigns%ROWTYPE; sg c10_demo.a056_segments%ROWTYPE; h text; prev jsonb; cid bigint; cu c10_demo.a056_customers%ROWTYPE; st jsonb; dec text; rsn text; el int:=0; bl int:=0; byr jsonb:='{}'; n int:=0; ids bigint[];
BEGIN
 SELECT * INTO c FROM c10_demo.a056_campaigns WHERE id=p_campaign FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(c.business_id,NULL,'campaign.dispatch',false,true);
 h:=c10_demo.a056_h(p_campaign::text); prev:=c10_demo.a056_idem_check(c.business_id,p_request,'dispatch_campaign',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF c.status<>'draft' THEN RAISE EXCEPTION 'A056_CAMPAIGN_TRANSITION'; END IF;
 SELECT * INTO sg FROM c10_demo.a056_segments WHERE id=c.segment_id;
 ids:=c10_demo.a056_segment_ids(c.business_id,sg.definition-'has_consent');
 FOREACH cid IN ARRAY ids LOOP
  SELECT * INTO cu FROM c10_demo.a056_customers WHERE id=cid; n:=n+1;
  st:=c10_demo.a056_consent_state(cid,c.channel,'marketing'); dec:='blocked'; rsn:=st->>'reason';
  IF (st->>'can_send')::boolean THEN
   IF (c.channel='email' AND cu.email_norm IS NULL) OR (c.channel IN('sms','phone','whatsapp') AND cu.phone_norm IS NULL) THEN rsn:='no_address'; ELSE dec:='send'; END IF; END IF;
  INSERT INTO c10_demo.a056_campaign_recipients(tenant_id,business_id,campaign_id,customer_id,decision,reason,provider_status) VALUES(c.tenant_id,c.business_id,c.id,cid,dec,rsn,CASE WHEN dec='send' THEN 'NOOP_NOT_SENT' ELSE 'BLOCKED_NOT_SENT' END);
  IF dec='send' THEN el:=el+1; ELSE bl:=bl+1; byr:=jsonb_set(byr,ARRAY[rsn],to_jsonb(COALESCE((byr->>rsn)::int,0)+1)); END IF;
 END LOOP;
 UPDATE c10_demo.a056_campaigns SET status='dispatched_noop',dispatched_at=now(),version=version+1 WHERE id=c.id;
 PERFORM c10_demo.a056_log(c.tenant_id,c.business_id,'campaign.dispatch_noop','campaign',c.id,p_request,jsonb_build_object('eligible',el,'blocked',bl));
 RETURN c10_demo.a056_done(c.business_id,p_request,'dispatch_campaign',h,jsonb_build_object('campaign_id',c.id,'considered',n,'eligible',el,'blocked',bl,'by_reason',byr,'provider','NOOP','sent',0,'note','NO-OP provider: nothing was sent; provider activation is NOT ENABLED'));
END $f$;
CREATE FUNCTION c10_demo.a056_list_campaigns_v1(p_business bigint,p_limit int DEFAULT 50) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
BEGIN PERFORM c10_demo.a056_require(p_business,NULL,'campaign.write');
 RETURN jsonb_build_object('items',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'channel',channel,'segment_id',segment_id,'status',status,'provider',provider,'version',version,'dispatched_at',dispatched_at) ORDER BY id DESC)
  FROM (SELECT * FROM c10_demo.a056_campaigns WHERE business_id=p_business ORDER BY id DESC LIMIT LEAST(GREATEST(COALESCE(p_limit,50),1),200)) q),'[]'));
END $f$;
CREATE FUNCTION c10_demo.a056_read_campaign_v1(p_campaign bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE c c10_demo.a056_campaigns%ROWTYPE;
BEGIN SELECT * INTO c FROM c10_demo.a056_campaigns WHERE id=p_campaign; IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(c.business_id,NULL,'campaign.write',false,true);
 RETURN jsonb_build_object('campaign',to_jsonb(c)-'request_key'-'created_by','recipients',COALESCE((SELECT jsonb_agg(jsonb_build_object('customer_id',customer_id,'decision',decision,'reason',reason,'provider_status',provider_status) ORDER BY id) FROM c10_demo.a056_campaign_recipients WHERE campaign_id=c.id),'[]'));
END $f$;

-- ---------- intake contracts ----------
CREATE FUNCTION c10_demo.a056_create_intake_endpoint_v1(p_business bigint,p_site bigint,p_channel text,p_label text,p_rate_limit_per_hour int,p_request text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE t bigint; h text; prev jsonb; id bigint; tok text;
BEGIN
 t:=c10_demo.a056_require(p_business,p_site,'intake.manage');
 h:=c10_demo.a056_h(p_site::text,p_channel,p_label,p_rate_limit_per_hour::text);
 -- token is shown once; a replay returns the receipt WITHOUT the token
 prev:=c10_demo.a056_idem_check(p_business,p_request,'create_intake',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF p_channel NOT IN('website','ecommerce','pos','offline','phone') OR COALESCE(p_rate_limit_per_hour,0) NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 tok:='c10in_'||replace(gen_random_uuid()::text||gen_random_uuid()::text,'-','');
 INSERT INTO c10_demo.a056_intake_endpoints(tenant_id,business_id,site_id,channel,label,token_hash,rate_limit_per_hour,request_key,created_by) VALUES(t,p_business,p_site,p_channel,c10_demo.a056_txt(p_label,100,true),c10_demo.a056_sha(tok),p_rate_limit_per_hour,p_request,c10_demo.actor_uid()) RETURNING a056_intake_endpoints.id INTO id;
 PERFORM c10_demo.a056_log(t,p_business,'intake.create','intake_endpoint',id,p_request,jsonb_build_object('channel',p_channel));
 PERFORM c10_demo.a056_done(p_business,p_request,'create_intake',h,jsonb_build_object('endpoint_id',id,'token',NULL,'token_note','shown once at creation'));
 RETURN jsonb_build_object('endpoint_id',id,'token',tok,'replayed',false);
END $f$;
CREATE FUNCTION c10_demo.a056_revoke_intake_endpoint_v1(p_endpoint bigint,p_request text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE e c10_demo.a056_intake_endpoints%ROWTYPE; h text; prev jsonb;
BEGIN
 SELECT * INTO e FROM c10_demo.a056_intake_endpoints WHERE id=p_endpoint FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(e.business_id,NULL,'intake.manage',false,true);
 h:=c10_demo.a056_h(p_endpoint::text); prev:=c10_demo.a056_idem_check(e.business_id,p_request,'revoke_intake',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 UPDATE c10_demo.a056_intake_endpoints SET status='revoked' WHERE id=p_endpoint;
 PERFORM c10_demo.a056_log(e.tenant_id,e.business_id,'intake.revoke','intake_endpoint',p_endpoint,p_request);
 RETURN c10_demo.a056_done(e.business_id,p_request,'revoke_intake',h,jsonb_build_object('endpoint_id',p_endpoint,'status','revoked'));
END $f$;
CREATE FUNCTION c10_demo.a056_list_intake_endpoints_v1(p_business bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
BEGIN PERFORM c10_demo.a056_require(p_business,NULL,'intake.manage');
 RETURN jsonb_build_object('items',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'channel',channel,'label',label,'site_id',site_id,'rate_limit_per_hour',rate_limit_per_hour,'status',status,'created_at',created_at) ORDER BY id DESC) FROM c10_demo.a056_intake_endpoints WHERE business_id=p_business),'[]'));
END $f$;
CREATE FUNCTION c10_demo.a056_public_intake_v1(p_token text,p_idempotency text,p_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE e c10_demo.a056_intake_endpoints%ROWTYPE; intent text; nm text; em text; ph text; sj text; ms text; lines jsonb:='[]'; cons jsonb:='{}'; st text; ref text; id bigint; key text; x jsonb; n int; k text; existing c10_demo.a056_enquiries%ROWTYPE;
BEGIN
 IF p_token IS NULL OR length(p_token)>100 THEN RAISE EXCEPTION 'A056_TOKEN_INVALID'; END IF;
 SELECT * INTO e FROM c10_demo.a056_intake_endpoints WHERE token_hash=c10_demo.a056_sha(p_token);
 IF NOT FOUND OR e.status<>'active' OR NOT c10_demo.a056_enabled(e.business_id) THEN RAISE EXCEPTION 'A056_TOKEN_INVALID'; END IF;
 IF p_idempotency IS NULL OR p_idempotency !~ '^[A-Za-z0-9_-]{8,100}$' THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 key:='in-'||e.id||'-'||p_idempotency;
 PERFORM pg_advisory_xact_lock(hashtextextended(key,56));
 SELECT * INTO existing FROM c10_demo.a056_enquiries WHERE business_id=e.business_id AND request_key=key;
 IF FOUND THEN RETURN jsonb_build_object('reference',existing.reference,'status',existing.status,'replayed',true); END IF;
 SELECT count(*) INTO n FROM c10_demo.a056_intake_log WHERE endpoint_id=e.id AND created_at>now()-interval '1 hour';
 IF n>=e.rate_limit_per_hour THEN RAISE EXCEPTION 'A056_THROTTLED'; END IF;
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::text)>20000 THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 FOR k IN SELECT jsonb_object_keys(p_payload) LOOP IF k NOT IN('intent','name','email','phone','subject','message','lines','consent') THEN RAISE EXCEPTION 'A056_INVALID'; END IF; END LOOP;
 intent:=COALESCE(p_payload->>'intent','enquiry'); IF intent NOT IN('enquiry','quote_request','order_request') THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 nm:=c10_demo.a056_txt(p_payload->>'name',200); em:=c10_demo.a056_txt(p_payload->>'email',254); ph:=c10_demo.a056_txt(p_payload->>'phone',32);
 PERFORM c10_demo.a056_email_norm(em); PERFORM c10_demo.a056_phone_norm(ph);
 sj:=c10_demo.a056_txt(p_payload->>'subject',200); ms:=c10_demo.a056_txt(p_payload->>'message',4000);
 IF em IS NULL AND ph IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 IF sj IS NULL THEN sj:=initcap(replace(intent,'_',' ')); END IF;
 IF p_payload ? 'lines' THEN
  IF jsonb_typeof(p_payload->'lines')<>'array' OR jsonb_array_length(p_payload->'lines')>50 THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
  FOR x IN SELECT * FROM jsonb_array_elements(p_payload->'lines') LOOP
   IF jsonb_typeof(x)<>'object' OR (x->>'quantity')::numeric<=0 OR (x->>'quantity')::numeric>1000000 THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
   lines:=lines||jsonb_build_object('description',c10_demo.a056_txt(x->>'description',200,true),'quantity',(x->>'quantity')::numeric,'sku',c10_demo.a056_txt(x->>'sku',60));
  END LOOP;
 END IF;
 IF p_payload ? 'consent' THEN
  IF jsonb_typeof(p_payload->'consent')<>'object' THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
  FOR k IN SELECT jsonb_object_keys(p_payload->'consent') LOOP
   IF k NOT IN('marketing_email','marketing_sms') OR jsonb_typeof(p_payload->'consent'->k)<>'boolean' THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
   cons:=cons||jsonb_build_object(k,p_payload->'consent'->k);
  END LOOP;
 END IF;
 st:=CASE WHEN intent='order_request' THEN 'DRAFT' ELSE 'RECEIVED' END;
 ref:='ENQ-'||upper(substr(c10_demo.a056_sha(key||clock_timestamp()::text),1,12));
 INSERT INTO c10_demo.a056_enquiries(tenant_id,business_id,site_id,channel,intent,subject,body,contact_name,contact_email,contact_phone,payload,endpoint_id,reference,status,request_key)
 VALUES(e.tenant_id,e.business_id,e.site_id,e.channel,intent,sj,ms,nm,em,ph,jsonb_build_object('lines',lines,'consent',cons,'unverified',true,'effect','none: no order, stock, payment or refund is created'),e.id,ref,st,key) RETURNING a056_enquiries.id INTO id;
 INSERT INTO c10_demo.a056_intake_log(endpoint_id) VALUES(e.id);
 INSERT INTO c10_demo.a056_audit(tenant_id,business_id,actor,action,entity,entity_id,request_key,detail) VALUES(e.tenant_id,e.business_id,NULL,'intake.received','enquiry',id,key,jsonb_build_object('channel',e.channel,'status',st));
 RETURN jsonb_build_object('reference',ref,'status',st,'replayed',false);
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'A056_INVALID';
END $f$;

-- ---------- reports ----------
CREATE FUNCTION c10_demo.a056_range(p_from timestamptz,p_to timestamptz,OUT f timestamptz,OUT t timestamptz) LANGUAGE sql IMMUTABLE AS $f$ SELECT COALESCE(p_from,now()-interval '30 days'),COALESCE(p_to,now()+interval '1 second') $f$;
CREATE FUNCTION c10_demo.a056_report_dashboard_v1(p_business bigint,p_from timestamptz DEFAULT NULL,p_to timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE f timestamptz; t timestamptz;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'report.read',true); SELECT * INTO f,t FROM c10_demo.a056_range(p_from,p_to);
 RETURN jsonb_build_object('business_id',p_business,'from',f,'to',t,
  'customers',(SELECT count(*) FROM c10_demo.a056_customers x WHERE x.business_id=p_business AND x.status='active' AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
  'leads',(SELECT count(*) FROM c10_demo.a056_leads x WHERE x.business_id=p_business AND x.created_at>=f AND x.created_at<t AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
  'enquiries',(SELECT count(*) FROM c10_demo.a056_enquiries x WHERE x.business_id=p_business AND x.created_at>=f AND x.created_at<t AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
  'opportunities_open',(SELECT count(*) FROM c10_demo.a056_opportunities x WHERE x.business_id=p_business AND x.status='open' AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
  'quotes_pending_approval',(SELECT count(*) FROM c10_demo.a056_quotations q JOIN c10_demo.a056_quote_versions v ON v.quotation_id=q.id AND v.version_no=q.current_version WHERE q.business_id=p_business AND v.status='pending_approval' AND c10_demo.a056_row_ok(q.tenant_id,q.business_id,q.site_id)),
  'tickets_open',(SELECT count(*) FROM c10_demo.a056_tickets x WHERE x.business_id=p_business AND x.status NOT IN('resolved','closed') AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
  'followups_overdue',(SELECT count(*) FROM c10_demo.a056_followups x WHERE x.business_id=p_business AND x.status='open' AND x.due_at<now() AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
  'advisory_pipeline_value',(SELECT sum(x.expected_value) FROM c10_demo.a056_opportunities x WHERE x.business_id=p_business AND x.status='open' AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
  'certified',false,'note','Counts from CRM records; pipeline value is advisory (null when no values entered), not revenue.');
END $f$;
CREATE FUNCTION c10_demo.a056_report_funnel_v1(p_business bigint,p_from timestamptz DEFAULT NULL,p_to timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE f timestamptz; t timestamptz; c bigint[]; names text[]:=ARRAY['enquiries','leads','qualified_leads','opportunities','quotes_sent','quotes_accepted','orders_created','orders_posted']; i int; out jsonb:='[]'; prevc bigint; l bigint;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'report.read',true); SELECT * INTO f,t FROM c10_demo.a056_range(p_from,p_to);
 c:=ARRAY[
 (SELECT count(*) FROM c10_demo.a056_enquiries x WHERE x.business_id=p_business AND x.created_at>=f AND x.created_at<t AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
 (SELECT count(*) FROM c10_demo.a056_leads x WHERE x.business_id=p_business AND x.created_at>=f AND x.created_at<t AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
 (SELECT count(*) FROM c10_demo.a056_leads x WHERE x.business_id=p_business AND x.created_at>=f AND x.created_at<t AND x.status IN('qualified','converted') AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
 (SELECT count(*) FROM c10_demo.a056_opportunities x WHERE x.business_id=p_business AND x.created_at>=f AND x.created_at<t AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id)),
 (SELECT count(DISTINCT q.id) FROM c10_demo.a056_quotations q JOIN c10_demo.a056_quote_versions v ON v.quotation_id=q.id WHERE q.business_id=p_business AND q.created_at>=f AND q.created_at<t AND v.status IN('sent','accepted','declined','converted') AND c10_demo.a056_row_ok(q.tenant_id,q.business_id,q.site_id)),
 (SELECT count(DISTINCT q.id) FROM c10_demo.a056_quotations q JOIN c10_demo.a056_quote_versions v ON v.quotation_id=q.id WHERE q.business_id=p_business AND q.created_at>=f AND q.created_at<t AND v.status IN('accepted','converted') AND c10_demo.a056_row_ok(q.tenant_id,q.business_id,q.site_id)),
 (SELECT count(DISTINCT q.id) FROM c10_demo.a056_quotations q JOIN c10_demo.a056_quote_versions v ON v.quotation_id=q.id WHERE q.business_id=p_business AND q.created_at>=f AND q.created_at<t AND v.status='converted' AND c10_demo.a056_row_ok(q.tenant_id,q.business_id,q.site_id)),
 (SELECT count(DISTINCT k.quotation_id) FROM c10_demo.a056_order_links k JOIN c10_demo.a056_posted_links(p_business) p ON p.link_id=k.id WHERE k.created_at>=f AND k.created_at<t AND c10_demo.a056_row_ok(k.tenant_id,k.business_id,k.site_id))];
 FOR i IN 1..8 LOOP
  out:=out||jsonb_build_object('stage',names[i],'count',c[i],'rate_from_prev',CASE WHEN i=1 OR i=4 AND false OR c[GREATEST(i-1,1)]=0 THEN NULL ELSE round(c[i]::numeric/c[i-1],4) END);
 END LOOP;
 l:=c[2];
 RETURN jsonb_build_object('from',f,'to',t,'stages',out,'lead_to_order_rate',CASE WHEN l=0 THEN NULL ELSE round(c[7]::numeric/l,4) END,'note','Stages are independent counts of records created in range; rates null when previous count is 0.');
END $f$;
CREATE FUNCTION c10_demo.a056_report_retention_v1(p_business bigint,p_months int DEFAULT 12) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE m int:=LEAST(GREATEST(COALESCE(p_months,12),1),36);
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'report.read',true);
 RETURN jsonb_build_object('source','A049_posted_orders','purchase_date_basis','crm_order_link_created_at (A049 overview exposes no posted date)','certified',false,
  'cohorts',COALESCE((SELECT jsonb_agg(jsonb_build_object('cohort_month',to_char(cm,'YYYY-MM'),'customers',n,'repeat_customers',r,'repeat_rate',CASE WHEN n=0 THEN NULL ELSE round(r::numeric/n,4) END) ORDER BY cm) FROM
   (SELECT date_trunc('month',first_at) cm,count(*) n,count(*) FILTER (WHERE cnt>=2) r FROM (SELECT customer_id,min(created_at) first_at,count(DISTINCT order_id) cnt FROM c10_demo.a056_posted_links(p_business) p
     JOIN c10_demo.a056_customers c ON c.id=p.customer_id WHERE c10_demo.a056_row_ok(c.tenant_id,c.business_id,c.site_id) GROUP BY customer_id) z
    WHERE first_at>=date_trunc('month',now())-make_interval(months=>m-1) GROUP BY 1) q),'[]'));
END $f$;
CREATE FUNCTION c10_demo.a056_report_repeat_business_v1(p_business bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE n int; r int;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'report.read',true);
 SELECT count(*),count(*) FILTER (WHERE cnt>=2) INTO n,r FROM (SELECT p.customer_id,count(DISTINCT order_id) cnt FROM c10_demo.a056_posted_links(p_business) p JOIN c10_demo.a056_customers c ON c.id=p.customer_id WHERE c10_demo.a056_row_ok(c.tenant_id,c.business_id,c.site_id) GROUP BY 1) z;
 RETURN jsonb_build_object('customers_with_orders',n,'repeat_customers',r,'repeat_rate',CASE WHEN n=0 THEN NULL ELSE round(r::numeric/n,4) END,'certified',false);
END $f$;
CREATE FUNCTION c10_demo.a056_report_followups_v1(p_business bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE r jsonb;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'report.read',true);
 SELECT jsonb_build_object('overdue',COALESCE(jsonb_agg(j) FILTER (WHERE b='overdue'),'[]'),'due_today',COALESCE(jsonb_agg(j) FILTER (WHERE b='today'),'[]'),'upcoming',COALESCE(jsonb_agg(j) FILTER (WHERE b='upcoming'),'[]')) INTO r FROM
  (SELECT CASE WHEN due_at<now() AND due_at<date_trunc('day',now()) THEN 'overdue' WHEN due_at<date_trunc('day',now())+interval '1 day' THEN 'today' ELSE 'upcoming' END b,
   jsonb_build_object('id',id,'customer_id',customer_id,'due_at',due_at,'note',note,'assignee',assignee,'opportunity_id',opportunity_id,'ticket_id',ticket_id,'version',version) j
   FROM c10_demo.a056_followups x WHERE x.business_id=p_business AND x.status='open' AND x.due_at<now()+interval '7 days' AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id) ORDER BY due_at LIMIT 300) q;
 RETURN r;
END $f$;
CREATE FUNCTION c10_demo.a056_report_tickets_v1(p_business bigint,p_from timestamptz DEFAULT NULL,p_to timestamptz DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE f timestamptz; t timestamptz;
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'report.read',true); SELECT * INTO f,t FROM c10_demo.a056_range(p_from,p_to);
 RETURN (SELECT jsonb_build_object('from',f,'to',t,'opened',count(*),'resolved',count(*) FILTER (WHERE resolved_at IS NOT NULL),
  'sla_met',count(*) FILTER (WHERE resolved_at IS NOT NULL AND resolved_at<=sla_due_at),
  'sla_breached',count(*) FILTER (WHERE (resolved_at IS NOT NULL AND resolved_at>sla_due_at) OR (resolved_at IS NULL AND now()>sla_due_at)),
  'avg_resolution_hours',round((avg(extract(epoch FROM resolved_at-created_at)/3600) FILTER (WHERE resolved_at IS NOT NULL))::numeric,2),
  'by_priority',jsonb_build_object('urgent',count(*) FILTER (WHERE priority='urgent'),'standard',count(*) FILTER (WHERE priority='standard'),'low',count(*) FILTER (WHERE priority='low')),
  'note','SLA hours are Owner-editable examples measured in calendar time.')
  FROM c10_demo.a056_tickets x WHERE x.business_id=p_business AND x.created_at>=f AND x.created_at<t AND c10_demo.a056_row_ok(x.tenant_id,x.business_id,x.site_id));
END $f$;

-- ---------- Customer 360 ----------
CREATE FUNCTION c10_demo.a056_read_customer360_v1(p_customer bigint) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE c c10_demo.a056_customers%ROWTYPE; fin jsonb; purchase jsonb;
BEGIN
 SELECT * INTO c FROM c10_demo.a056_customers WHERE id=p_customer; IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(c.business_id,c.site_id,'customer.read',false,true);
 IF NOT c10_demo.a056_row_ok(c.tenant_id,c.business_id,c.site_id) THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 fin:=CASE WHEN c10_demo.a056_authz(c.tenant_id,c.business_id,c.site_id,'finance.read') THEN c10_demo.a056_read_customer_finance_v1(p_customer) ELSE jsonb_build_object('status','RESTRICTED','balance_due',NULL,'payment_status',NULL) END;
 purchase:=c10_demo.a056_read_purchase_history_v1(p_customer);
 RETURN jsonb_build_object('customer',c10_demo.a056_cust_json(c),
  'contacts',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',k.id,'name',k.name,'role',k.role,'email',k.email,'phone',k.phone,'is_primary',k.is_primary,'status',k.status,'version',k.version) ORDER BY k.id) FROM c10_demo.a056_contacts k WHERE k.customer_id=c.id),'[]'),
  'consents',COALESCE((SELECT jsonb_agg(jsonb_build_object('channel',ch,'purpose',pu,'state',c10_demo.a056_consent_state(c.id,ch,pu))) FROM unnest(ARRAY['email','sms','phone','whatsapp','post']) ch,unnest(ARRAY['marketing','service']) pu),'[]'),
  'comm_prefs',(SELECT to_jsonb(p)-'updated_by' FROM c10_demo.a056_comm_prefs p WHERE p.customer_id=c.id),
  'leads',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'status',status,'source',source,'version',version) ORDER BY id DESC) FROM c10_demo.a056_leads WHERE customer_id=c.id),'[]'),
  'enquiries',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'reference',reference,'status',status,'subject',subject,'channel',channel) ORDER BY id DESC) FROM c10_demo.a056_enquiries WHERE customer_id=c.id),'[]'),
  'opportunities',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'title',title,'stage',stage_code,'status',status,'expected_value',expected_value,'version',version) ORDER BY id DESC) FROM c10_demo.a056_opportunities WHERE customer_id=c.id),'[]'),
  'quotations',COALESCE((SELECT jsonb_agg(c10_demo.a056_quote_json(q,false) ORDER BY q.id DESC) FROM c10_demo.a056_quotations q WHERE q.customer_id=c.id),'[]'),
  'orders',purchase->'orders','purchase',purchase-'orders',
  'tickets',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',t.id,'kind',t.kind,'priority',t.priority,'status',t.status,'subject',t.subject,'sla_due_at',t.sla_due_at,'sla_state',c10_demo.a056_sla_state(t),'version',t.version) ORDER BY t.id DESC) FROM c10_demo.a056_tickets t WHERE t.customer_id=c.id),'[]'),
  'followups',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'due_at',due_at,'status',status,'note',note,'version',version) ORDER BY due_at) FROM c10_demo.a056_followups WHERE customer_id=c.id),'[]'),
  'timeline',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'kind',kind,'direction',direction,'summary',summary,'occurred_at',occurred_at) ORDER BY occurred_at DESC,id DESC) FROM (SELECT * FROM c10_demo.a056_history WHERE customer_id=c.id ORDER BY occurred_at DESC,id DESC LIMIT 100) h),'[]'),
  'finance',fin);
END $f$;

-- ---------- privacy ----------
CREATE FUNCTION c10_demo.a056_export_customer_v1(p_customer bigint,p_request text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE c c10_demo.a056_customers%ROWTYPE; h text; prev jsonb; pkg jsonb;
BEGIN
 SELECT * INTO c FROM c10_demo.a056_customers WHERE id=p_customer; IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(c.business_id,c.site_id,'customer.export',false,true);
 IF NOT c10_demo.a056_row_ok(c.tenant_id,c.business_id,c.site_id) THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 h:=c10_demo.a056_h(p_customer::text); prev:=c10_demo.a056_idem_check(c.business_id,p_request,'export_customer',h);
 pkg:=jsonb_build_object('exported_at',now(),'customer',c10_demo.a056_cust_json(c),
  'contacts',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'created_by') FROM c10_demo.a056_contacts x WHERE customer_id=c.id),'[]'),
  'consent_events',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'recorded_by') FROM c10_demo.a056_consent_events x WHERE customer_id=c.id),'[]'),
  'history',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'actor') FROM c10_demo.a056_history x WHERE customer_id=c.id),'[]'),
  'leads',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'created_by') FROM c10_demo.a056_leads x WHERE customer_id=c.id),'[]'),
  'enquiries',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'created_by') FROM c10_demo.a056_enquiries x WHERE customer_id=c.id),'[]'),
  'opportunities',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'created_by') FROM c10_demo.a056_opportunities x WHERE customer_id=c.id),'[]'),
  'quotations',COALESCE((SELECT jsonb_agg(c10_demo.a056_quote_json(q,true)) FROM c10_demo.a056_quotations q WHERE q.customer_id=c.id),'[]'),
  'tickets',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'created_by') FROM c10_demo.a056_tickets x WHERE customer_id=c.id),'[]'),
  'followups',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'created_by') FROM c10_demo.a056_followups x WHERE customer_id=c.id),'[]'),
  'order_links',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'request_key'-'created_by') FROM c10_demo.a056_order_links x WHERE customer_id=c.id),'[]'));
 IF prev IS NOT NULL THEN RETURN pkg; END IF;
 PERFORM c10_demo.a056_log(c.tenant_id,c.business_id,'privacy.export','customer',c.id,p_request);
 PERFORM c10_demo.a056_done(c.business_id,p_request,'export_customer',h,jsonb_build_object('customer_id',c.id,'exported',true));
 RETURN pkg;
END $f$;
CREATE FUNCTION c10_demo.a056_export_customers_csv_v1(p_business bigint) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
BEGIN
 PERFORM c10_demo.a056_require(p_business,NULL,'customer.export');
 RETURN 'id,kind,display_name,legal_name,email,phone,status,tags'||COALESCE((SELECT string_agg(E'\r\n'||c.id||','||c.kind||','||c10_demo.a056_csv_cell(c.display_name)||','||c10_demo.a056_csv_cell(c.legal_name)||','||c10_demo.a056_csv_cell(c.email)||','||c10_demo.a056_csv_cell(c.phone)||','||c.status||','||c10_demo.a056_csv_cell(array_to_string(c.tags,';')),'' ORDER BY c.id)
  FROM c10_demo.a056_customers c WHERE c.business_id=p_business AND c10_demo.a056_row_ok(c.tenant_id,c.business_id,c.site_id)),'');
END $f$;
CREATE FUNCTION c10_demo.a056_redact_customer_v1(p_customer bigint,p_expected bigint,p_reason text,p_request text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=c10_demo,pg_catalog AS $f$
#variable_conflict use_column
DECLARE c c10_demo.a056_customers%ROWTYPE; h text; prev jsonb; nv bigint; ids bigint[];
BEGIN
 SELECT * INTO c FROM c10_demo.a056_customers WHERE id=p_customer FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'A056_NOT_FOUND'; END IF;
 PERFORM c10_demo.a056_require(c.business_id,c.site_id,'customer.redact',false,true);
 h:=c10_demo.a056_h(p_customer::text,p_expected::text,p_reason); prev:=c10_demo.a056_idem_check(c.business_id,p_request,'redact_customer',h); IF prev IS NOT NULL THEN RETURN prev; END IF;
 IF c.status='redacted' OR c.version<>p_expected THEN RAISE EXCEPTION '%',CASE WHEN c.status='redacted' THEN 'A056_CUSTOMER_NOT_ACTIVE' ELSE 'A056_STALE_CUSTOMER' END; END IF;
 IF c10_demo.a056_txt(p_reason,500) IS NULL THEN RAISE EXCEPTION 'A056_INVALID'; END IF;
 ids:=ARRAY(SELECT id FROM c10_demo.a056_customers WHERE id=p_customer OR merged_into=p_customer);
 IF EXISTS(SELECT 1 FROM c10_demo.a056_tickets WHERE customer_id=ANY(ids) AND status NOT IN('resolved','closed')) OR EXISTS(SELECT 1 FROM c10_demo.a056_followups WHERE customer_id=ANY(ids) AND status='open')
 THEN RAISE EXCEPTION 'A056_REDACT_BLOCKED_OPEN_WORK'; END IF;
 -- suppressions are kept by hash so opt-out survives redaction
 UPDATE c10_demo.a056_customers SET display_name=NULL,legal_name=NULL,email=NULL,phone=NULL,email_norm=NULL,phone_norm=NULL,tags='{}',status='redacted',version=version+1,updated_at=now() WHERE id=ANY(ids);
 UPDATE c10_demo.a056_contacts SET name=NULL,email=NULL,phone=NULL,email_norm=NULL,phone_norm=NULL,role=NULL,status='redacted',is_primary=false WHERE customer_id=ANY(ids);
 UPDATE c10_demo.a056_history SET summary='[redacted]' WHERE customer_id=ANY(ids);
 UPDATE c10_demo.a056_leads SET name=NULL,email=NULL,phone=NULL,email_norm=NULL,phone_norm=NULL,note=NULL WHERE customer_id=ANY(ids);
 UPDATE c10_demo.a056_enquiries SET contact_name=NULL,contact_email=NULL,contact_phone=NULL,subject='[redacted]',body=NULL,payload='{"redacted":true}' WHERE customer_id=ANY(ids);
 UPDATE c10_demo.a056_tickets SET description=NULL,resolution_note=CASE WHEN resolution_note IS NULL THEN NULL ELSE '[redacted]' END,subject='[redacted]' WHERE customer_id=ANY(ids);
 UPDATE c10_demo.a056_followups SET note=NULL,outcome_note=NULL WHERE customer_id=ANY(ids);
 UPDATE c10_demo.a056_opportunities SET title='[redacted]' WHERE customer_id=ANY(ids);
 DELETE FROM c10_demo.a056_comm_prefs WHERE customer_id=ANY(ids);
 SELECT version INTO nv FROM c10_demo.a056_customers WHERE id=p_customer;
 PERFORM c10_demo.a056_log(c.tenant_id,c.business_id,'privacy.redact','customer',p_customer,p_request,jsonb_build_object('records',cardinality(ids)));
 RETURN c10_demo.a056_done(c.business_id,p_request,'redact_customer',h,jsonb_build_object('customer_id',p_customer,'status','redacted','version',nv));
END $f$;

-- ---------- RLS & grants ----------
DO $rls$
DECLARE r record; direct text[]:=ARRAY['a056_settings','a056_settings_history','a056_audit','a056_customers','a056_contacts','a056_history','a056_consent_events','a056_comm_prefs','a056_leads','a056_enquiries','a056_opportunities','a056_opp_stage_log',
 'a056_quotations','a056_quote_versions','a056_quote_lines','a056_order_links','a056_followups','a056_tickets','a056_ticket_events','a056_dup_candidates','a056_merge_log','a056_segments','a056_campaigns','a056_campaign_recipients'];
 hs boolean;
BEGIN
 FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='c10_demo' AND c.relkind='r' AND c.relname LIKE 'a056\_%' LOOP
  EXECUTE format('ALTER TABLE c10_demo.%I ENABLE ROW LEVEL SECURITY',r.relname);
  EXECUTE format('REVOKE ALL ON c10_demo.%I FROM PUBLIC,anon,authenticated',r.relname);
  IF r.relname=ANY(direct) THEN
   hs:=EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='c10_demo' AND table_name=r.relname AND column_name='site_id');
   EXECUTE format('GRANT SELECT ON c10_demo.%I TO authenticated',r.relname);
   IF r.relname IN('a056_audit','a056_settings_history','a056_dup_candidates','a056_merge_log') THEN
    EXECUTE format('CREATE POLICY a056_read ON c10_demo.%I FOR SELECT TO authenticated USING(c10_demo.a056_row_ok(tenant_id,business_id,NULL) AND c10_demo.a056_authz(tenant_id,business_id,NULL,%L))',r.relname,'customer.merge');
   ELSIF hs THEN
    EXECUTE format('CREATE POLICY a056_read ON c10_demo.%I FOR SELECT TO authenticated USING(c10_demo.a056_row_ok(tenant_id,business_id,site_id))',r.relname);
   ELSE
    EXECUTE format('CREATE POLICY a056_read ON c10_demo.%I FOR SELECT TO authenticated USING(c10_demo.a056_row_ok(tenant_id,business_id,NULL))',r.relname);
   END IF;
  END IF;
 END LOOP;
 REVOKE ALL ON ALL SEQUENCES IN SCHEMA c10_demo FROM PUBLIC,anon,authenticated;
 FOR r IN SELECT p.oid::regprocedure::text sig,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='c10_demo' AND p.proname LIKE 'a056\_%' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',r.sig);
  IF r.proname ~ '_v1$' AND r.proname NOT IN('a056_audit_immutable') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',r.sig); END IF;
  IF r.proname IN('a056_row_ok','a056_authz','a056_enabled','a056_cfg','a056_tier') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',r.sig); END IF;
  IF r.proname='a056_public_intake_v1' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO anon',r.sig); END IF;
 END LOOP;
END $rls$;
